// ===== Brand colors =====
const COLORS = {
  black: '#000000',
  white: '#ffffff',
  green: '#00FF00',
};

// ===== State =====
const state = {
  word1: 'WORK',
  word2: 'PLAY',
  rotX: 20,
  width: 450,
  height: 70,
  depth: 70,
  fontSize: 77,
  perspective: 800,
  bgColor: COLORS.black,
  side1Bg: COLORS.black,
  side1Text: COLORS.white,
  side2Bg: COLORS.green,
  side2Text: COLORS.black,
};

// ===== Font for SVG outline export =====
let otFont = null;

// Embedded subset font (uppercase A-Z, digits, punctuation, Cyrillic)
const FONT_BASE64 = '';

function loadEmbeddedFont() {
  try {
    const raw = atob(FONT_BASE64);
    const buf = new ArrayBuffer(raw.length);
    const view = new Uint8Array(buf);
    for (let i = 0; i < raw.length; i++) view[i] = raw.charCodeAt(i);
    otFont = opentype.parse(buf);
  } catch (e) {
    console.warn('Could not parse embedded font:', e);
  }
}

loadEmbeddedFont();

// ===== DOM =====
const $ = id => document.getElementById(id);

const els = {
  box: $('box'),
  faces: {
    front: $('faceFront'),
    back: $('faceBack'),
    top: $('faceTop'),
    bottom: $('faceBottom'),
    left: $('faceLeft'),
    right: $('faceRight'),
  },
  preview: $('preview'),
  angleBadge: $('angleBadge'),
  toast: $('toast'),
};

// ===== Swatch logic =====
function initSwatches() {
  document.querySelectorAll('.swatch-group').forEach(group => {
    const key = group.dataset.key;
    const swatches = group.querySelectorAll('.swatch');

    // Set initial active state
    swatches.forEach(s => {
      if (COLORS[s.dataset.color] === state[key]) s.classList.add('active');
      s.addEventListener('click', () => {
        swatches.forEach(x => x.classList.remove('active'));
        s.classList.add('active');
        state[key] = COLORS[s.dataset.color];
        updateScene();
      });
    });
  });
}

// ===== Update scene =====
function updateScene() {
  state.word1 = $('word1').value.toUpperCase() || 'WORD';
  state.word2 = $('word2').value.toUpperCase() || 'WORD';
  state.rotX = parseFloat($('rotationX').value);
  state.width = parseFloat($('boxWidth').value);
  state.height = parseFloat($('boxHeight').value);
  state.depth = parseFloat($('boxDepth').value);
  state.fontSize = parseFloat($('fontSize').value);

  // Value displays
  $('rotVal').textContent = state.rotX + '°';
  $('wVal').textContent = state.width;
  $('hVal').textContent = state.height;
  $('dVal').textContent = state.depth;
  $('fsVal').textContent = state.fontSize;

  // Background
  els.preview.style.background = state.bgColor;

  const { width: W, height: H, depth: D, rotX, fontSize } = state;
  const halfH = H / 2, halfD = D / 2, halfW = W / 2;
  const fs = `font-size:${fontSize}px;`;

  els.box.style.width = W + 'px';
  els.box.style.height = H + 'px';
  els.box.style.transform = `rotateX(${rotX}deg)`;

  // Front/Back = Side 1
  applyFace(els.faces.front, W, H, `translateZ(${halfD}px)`, state.word1, state.side1Bg, state.side1Text, fs);
  applyFace(els.faces.back, W, H, `rotateX(180deg) translateZ(${halfD}px)`, state.word1, state.side1Bg, state.side1Text, fs);

  // Top/Bottom = Side 2
  applyFace(els.faces.top, W, D, `rotateX(90deg) translateZ(${halfH}px)`, state.word2, state.side2Bg, state.side2Text, fs);
  applyFace(els.faces.bottom, W, D, `rotateX(-90deg) translateZ(${halfH}px)`, state.word2, state.side2Bg, state.side2Text, fs);

  // Left/Right = Side 1 bg, no text
  applyFace(els.faces.left, D, H, `rotateY(-90deg) translateZ(${halfW}px)`, '', state.side1Bg, '', '');
  applyFace(els.faces.right, D, H, `rotateY(90deg) translateZ(${halfW}px)`, '', state.side1Bg, '', '');

  els.angleBadge.textContent = state.rotX + '°';
}

function applyFace(el, w, h, transform, text, bg, color, fontStyle) {
  el.style.cssText = `width:${w}px;height:${h}px;transform:${transform};background:${bg};color:${color};${fontStyle}`;
  el.textContent = text;
}

// ===== Input bindings =====
['word1','word2','rotationX','boxWidth','boxHeight','boxDepth','fontSize'].forEach(id => {
  $(id).addEventListener('input', updateScene);
});

// ===== Drag to rotate =====
let isDragging = false, dragStartY = 0, dragStartRot = 0;

els.preview.addEventListener('mousedown', e => {
  isDragging = true;
  dragStartY = e.clientY;
  dragStartRot = state.rotX;
  e.preventDefault();
});

window.addEventListener('mousemove', e => {
  if (!isDragging) return;
  const delta = (dragStartY - e.clientY) * 0.4;
  let newRot = Math.max(-90, Math.min(90, Math.round(dragStartRot + delta)));
  $('rotationX').value = newRot;
  updateScene();
});

window.addEventListener('mouseup', () => { isDragging = false; });

els.preview.addEventListener('touchstart', e => {
  isDragging = true;
  dragStartY = e.touches[0].clientY;
  dragStartRot = state.rotX;
}, { passive: true });

window.addEventListener('touchmove', e => {
  if (!isDragging) return;
  const delta = (dragStartY - e.touches[0].clientY) * 0.4;
  let newRot = Math.max(-90, Math.min(90, Math.round(dragStartRot + delta)));
  $('rotationX').value = newRot;
  updateScene();
}, { passive: true });

window.addEventListener('touchend', () => { isDragging = false; });


// =========================================
// ===== SVG EXPORT ENGINE =================
// =========================================

// Strategy: get glyph outlines from opentype.js, linearize all Bezier curves
// into short line segments, then project each point through the full 3D pipeline
// (place on face plane → rotate around X → perspective project).
// Linearizing first avoids the Bezier-through-perspective distortion problem.

// Subdivide a quadratic Bezier into line segments
function flattenQuad(x0, y0, cx, cy, x1, y1, steps) {
  const pts = [];
  for (let i = 1; i <= steps; i++) {
    const t = i / steps;
    const mt = 1 - t;
    pts.push({
      x: mt*mt*x0 + 2*mt*t*cx + t*t*x1,
      y: mt*mt*y0 + 2*mt*t*cy + t*t*y1,
    });
  }
  return pts;
}

// Subdivide a cubic Bezier into line segments
function flattenCubic(x0, y0, cx1, cy1, cx2, cy2, x1, y1, steps) {
  const pts = [];
  for (let i = 1; i <= steps; i++) {
    const t = i / steps;
    const mt = 1 - t;
    pts.push({
      x: mt*mt*mt*x0 + 3*mt*mt*t*cx1 + 3*mt*t*t*cx2 + t*t*t*x1,
      y: mt*mt*mt*y0 + 3*mt*mt*t*cy1 + 3*mt*t*t*cy2 + t*t*t*y1,
    });
  }
  return pts;
}

// Convert opentype path commands into arrays of 2D polyline points (one array per sub-path).
// All curves are linearized into line segments.
function linearizeGlyphPath(commands, steps) {
  const subPaths = [];
  let current = [];
  let cx = 0, cy = 0; // current point

  for (const cmd of commands) {
    switch (cmd.type) {
      case 'M':
        if (current.length > 0) subPaths.push(current);
        current = [{ x: cmd.x, y: cmd.y }];
        cx = cmd.x; cy = cmd.y;
        break;
      case 'L':
        current.push({ x: cmd.x, y: cmd.y });
        cx = cmd.x; cy = cmd.y;
        break;
      case 'Q': {
        const seg = flattenQuad(cx, cy, cmd.x1, cmd.y1, cmd.x, cmd.y, steps);
        current.push(...seg);
        cx = cmd.x; cy = cmd.y;
        break;
      }
      case 'C': {
        const seg = flattenCubic(cx, cy, cmd.x1, cmd.y1, cmd.x2, cmd.y2, cmd.x, cmd.y, steps);
        current.push(...seg);
        cx = cmd.x; cy = cmd.y;
        break;
      }
      case 'Z':
        if (current.length > 0) {
          subPaths.push(current);
          current = [];
        }
        break;
    }
  }
  if (current.length > 0) subPaths.push(current);
  return subPaths;
}

// Build SVG path d-string for word on a 3D face.
// Text is laid out flat, centered on face, then each point is:
//   1. Placed in the face's 3D coordinate system
//   2. Rotated around X axis by theta
//   3. Perspective-projected to 2D
function buildTextPathSVG(word, fs, faceOrigin, uAxis, vAxis, faceW, faceH, theta, perspDist, svgOffset) {
  if (!otFont) return null;

  // Get glyph outlines
  const path = otFont.getPath(word, 0, 0, fs);
  const bbox = path.getBoundingBox();
  const textW = bbox.x2 - bbox.x1;

  // Scale to fit face width
  const scale = textW > faceW * 0.9 ? (faceW * 0.9) / textW : 1;

  // Center offsets: map glyph bbox center to face center (0,0 in face-local coords)
  const ox = -(bbox.x1 + bbox.x2) / 2 * scale;
  const oy = -(bbox.y1 + bbox.y2) / 2 * scale;

  const cosT = Math.cos(theta), sinT = Math.sin(theta);

  // Project a 2D glyph point (in scaled, centered face-local coords) to SVG 2D
  function proj(gx, gy) {
    const lx = gx * scale + ox;
    const ly = gy * scale + oy;

    // Place on 3D face plane
    const x3 = faceOrigin.x + uAxis.x * lx + vAxis.x * ly;
    const y3 = faceOrigin.y + uAxis.y * lx + vAxis.y * ly;
    const z3 = faceOrigin.z + uAxis.z * lx + vAxis.z * ly;

    // Rotate around X
    const ry = y3 * cosT - z3 * sinT;
    const rz = y3 * sinT + z3 * cosT;

    // Perspective project (CSS convention: +z = toward viewer)
    const s = perspDist / (perspDist - rz);
    return {
      x: x3 * s + svgOffset.x,
      y: ry * s + svgOffset.y,
    };
  }

  // Linearize all curves into polylines (8 segments per curve for smooth result)
  const subPaths = linearizeGlyphPath(path.commands, 8);

  // Build SVG path with only M and L commands (all curves are now line segments)
  let d = '';
  for (const sp of subPaths) {
    for (let i = 0; i < sp.length; i++) {
      const p = proj(sp[i].x, sp[i].y);
      d += i === 0 ? `M${p.x.toFixed(2)},${p.y.toFixed(2)}` : `L${p.x.toFixed(2)},${p.y.toFixed(2)}`;
    }
    d += 'Z';
  }
  return d;
}


function generateSVG() {
  const { width: W, height: H, depth: D, rotX, fontSize, perspective: perspDist } = state;
  const theta = rotX * Math.PI / 180;

  const hw = W/2, hh = H/2, hd = D/2;
  const verts = [
    { x: -hw, y: -hh, z:  hd }, { x:  hw, y: -hh, z:  hd },
    { x:  hw, y:  hh, z:  hd }, { x: -hw, y:  hh, z:  hd },
    { x: -hw, y: -hh, z: -hd }, { x:  hw, y: -hh, z: -hd },
    { x:  hw, y:  hh, z: -hd }, { x: -hw, y:  hh, z: -hd },
  ];

  // Rotate around X
  const cosT = Math.cos(theta), sinT = Math.sin(theta);
  const rotated = verts.map(v => ({
    x: v.x,
    y: v.y * cosT - v.z * sinT,
    z: v.y * sinT + v.z * cosT,
  }));

  // Perspective project vertices
  const pad = 20;
  const projected = rotated.map(v => {
    const s = perspDist / (perspDist - v.z);
    return { x: v.x * s, y: v.y * s, z: v.z };
  });

  let minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity;
  projected.forEach(p => {
    minX = Math.min(minX, p.x); maxX = Math.max(maxX, p.x);
    minY = Math.min(minY, p.y); maxY = Math.max(maxY, p.y);
  });

  const svgW = (maxX - minX) + pad * 2;
  const svgH = (maxY - minY) + pad * 2;
  const cx = -minX + pad, cy = -minY + pad;
  const pts = projected.map(p => ({ x: p.x + cx, y: p.y + cy, z: p.z }));

  // Face definitions with 3D geometry for text placement
  const faces = [
    { vi: [0,1,2,3], fill: state.side1Bg, textFill: state.side1Text, word: state.word1,
      origin: {x:0, y:0, z:hd}, uAxis: {x:1,y:0,z:0}, vAxis: {x:0,y:1,z:0}, faceW: W, faceH: H },
    { vi: [5,4,7,6], fill: state.side1Bg, textFill: state.side1Text, word: state.word1,
      origin: {x:0, y:0, z:-hd}, uAxis: {x:-1,y:0,z:0}, vAxis: {x:0,y:1,z:0}, faceW: W, faceH: H },
    { vi: [4,5,1,0], fill: state.side2Bg, textFill: state.side2Text, word: state.word2,
      origin: {x:0, y:-hh, z:0}, uAxis: {x:1,y:0,z:0}, vAxis: {x:0,y:0,z:1}, faceW: W, faceH: D },
    { vi: [3,2,6,7], fill: state.side2Bg, textFill: state.side2Text, word: state.word2,
      origin: {x:0, y:hh, z:0}, uAxis: {x:1,y:0,z:0}, vAxis: {x:0,y:0,z:-1}, faceW: W, faceH: D },
    { vi: [4,0,3,7], fill: state.side1Bg, textFill: state.side1Text, word: null,
      origin: {x:-hw, y:0, z:0}, uAxis: {x:0,y:0,z:1}, vAxis: {x:0,y:1,z:0}, faceW: D, faceH: H },
    { vi: [1,5,6,2], fill: state.side1Bg, textFill: state.side1Text, word: null,
      origin: {x:hw, y:0, z:0}, uAxis: {x:0,y:0,z:-1}, vAxis: {x:0,y:1,z:0}, faceW: D, faceH: H },
  ];

  // Back-face culling + depth sort
  const sub = (a, b) => ({ x: a.x-b.x, y: a.y-b.y, z: a.z-b.z });
  const cross = (a, b) => ({ x: a.y*b.z-a.z*b.y, y: a.z*b.x-a.x*b.z, z: a.x*b.y-a.y*b.x });
  const dot = (a, b) => a.x*b.x + a.y*b.y + a.z*b.z;

  const visible = [];
  for (const face of faces) {
    const [i0,i1,i2] = face.vi;
    const normal = cross(sub(rotated[i1], rotated[i0]), sub(rotated[i2], rotated[i0]));
    const centroid = {
      x: face.vi.reduce((s,i) => s+rotated[i].x, 0)/4,
      y: face.vi.reduce((s,i) => s+rotated[i].y, 0)/4,
      z: face.vi.reduce((s,i) => s+rotated[i].z, 0)/4,
    };
    const viewVec = { x: -centroid.x, y: -centroid.y, z: perspDist - centroid.z };
    if (dot(normal, viewVec) > 0.01) {
      visible.push({ ...face, avgZ: centroid.z });
    }
  }
  visible.sort((a, b) => a.avgZ - b.avgZ);

  // Build SVG
  let svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${Math.round(svgW)}" height="${Math.round(svgH)}" viewBox="0 0 ${svgW.toFixed(2)} ${svgH.toFixed(2)}">\n`;

  for (const face of visible) {
    const facePoints = face.vi.map(i => `${pts[i].x.toFixed(2)},${pts[i].y.toFixed(2)}`).join(' ');
    svg += `<polygon points="${facePoints}" fill="${face.fill}" stroke="none"/>\n`;

    if (face.word) {
      const fs = fontSize;
      const svgOffset = { x: cx, y: cy };
      const pathD = buildTextPathSVG(
        face.word, fs,
        face.origin, face.uAxis, face.vAxis,
        face.faceW, face.faceH,
        theta, perspDist, svgOffset
      );
      if (pathD) {
        svg += `<path d="${pathD}" fill="${face.textFill}" fill-rule="evenodd"/>\n`;
      }
    }
  }

  svg += `</svg>`;
  return svg;
}

// ===== Copy / Download =====
function showToast(msg) {
  els.toast.textContent = msg;
  els.toast.classList.add('show');
  setTimeout(() => els.toast.classList.remove('show'), 2000);
}

$('copySvgBtn').addEventListener('click', async () => {
  const svg = generateSVG();
  try {
    await navigator.clipboard.writeText(svg);
    showToast('SVG copied to clipboard');
  } catch {
    const ta = document.createElement('textarea');
    ta.value = svg;
    document.body.appendChild(ta);
    ta.select();
    document.execCommand('copy');
    document.body.removeChild(ta);
    showToast('SVG copied to clipboard');
  }
});

$('downloadSvgBtn').addEventListener('click', () => {
  const svg = generateSVG();
  const blob = new Blob([svg], { type: 'image/svg+xml' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = `${state.word1}-${state.word2}.svg`;
  a.click();
  URL.revokeObjectURL(url);
  showToast('SVG downloaded');
});

// ===== PNG Export =====
$('downloadPngBtn').addEventListener('click', async () => {
  // Capture the 3D scene by cloning the preview area into an SVG foreignObject,
  // rendering that to a canvas, then downloading as PNG.
  try {
    const scene = document.querySelector('.scene');
    const preview = els.preview;
    const rect = scene.getBoundingClientRect();
    const previewRect = preview.getBoundingClientRect();

    // We want to capture just the 3D box area with some padding
    const scale = 2; // 2x for retina quality
    const padPx = 40;

    // Get computed styles we need
    const bgColor = state.bgColor;

    // Build inline HTML with all styles baked in
    const boxEl = document.getElementById('box');
    const faces = boxEl.querySelectorAll('.face');
    let facesHTML = '';
    faces.forEach(f => {
      facesHTML += `<div style="${f.style.cssText};position:absolute;display:flex;align-items:center;justify-content:center;font-family:'Arial Black',Impact,sans-serif;text-transform:uppercase;white-space:nowrap;overflow:hidden;backface-visibility:hidden;">${f.textContent}</div>`;
    });

    // Scene dimensions (CSS pixels)
    const sceneW = rect.width + padPx * 2;
    const sceneH = rect.height + padPx * 2;

    const svgMarkup = `
      <svg xmlns="http://www.w3.org/2000/svg" width="${sceneW * scale}" height="${sceneH * scale}">
        <foreignObject width="${sceneW}" height="${sceneH}"
          style="transform:scale(${scale});transform-origin:0 0;">
          <div xmlns="http://www.w3.org/1999/xhtml" style="width:${sceneW}px;height:${sceneH}px;display:flex;align-items:center;justify-content:center;background:${bgColor};">
            <div style="perspective:800px;perspective-origin:50% 50%;">
              <div style="width:${state.width}px;height:${state.height}px;position:relative;transform-style:preserve-3d;transform:rotateX(${state.rotX}deg);">
                ${facesHTML}
              </div>
            </div>
          </div>
        </foreignObject>
      </svg>`;

    const blob = new Blob([svgMarkup], { type: 'image/svg+xml;charset=utf-8' });
    const url = URL.createObjectURL(blob);

    const img = new Image();
    img.onload = () => {
      const canvas = document.createElement('canvas');
      canvas.width = sceneW * scale;
      canvas.height = sceneH * scale;
      const ctx = canvas.getContext('2d');
      ctx.drawImage(img, 0, 0);
      URL.revokeObjectURL(url);

      canvas.toBlob(pngBlob => {
        const pngUrl = URL.createObjectURL(pngBlob);
        const a = document.createElement('a');
        a.href = pngUrl;
        a.download = `${state.word1}-${state.word2}.png`;
        a.click();
        URL.revokeObjectURL(pngUrl);
        showToast('PNG downloaded');
      }, 'image/png');
    };
    img.onerror = () => {
      URL.revokeObjectURL(url);
      // Fallback: try html2canvas
      fallbackPngExport();
    };
    img.src = url;
  } catch (err) {
    console.error('PNG export error:', err);
    fallbackPngExport();
  }
});

async function fallbackPngExport() {
  if (typeof html2canvas === 'undefined') {
    showToast('PNG export failed — html2canvas not loaded');
    return;
  }
  try {
    const scene = document.querySelector('.scene');
    const canvas = await html2canvas(scene, {
      backgroundColor: state.bgColor,
      scale: 2,
      useCORS: true,
    });
    canvas.toBlob(blob => {
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `${state.word1}-${state.word2}.png`;
      a.click();
      URL.revokeObjectURL(url);
      showToast('PNG downloaded');
    }, 'image/png');
  } catch (err) {
    console.error('html2canvas fallback failed:', err);
    showToast('PNG export failed');
  }
}

// ===== Init =====
initSwatches();
updateScene();
